def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D' if history[0][1] == 'D' else 'C'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]

    if 'C' not in opp:
        return 'D'

    if n == 99:
        return 'D'

    last_opp = opp[-1]
    last_me = me[-1]

    if last_opp == 'C':
        return 'C'

    k = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            k += 1
        else:
            break

    if k >= 3 and k % 3 == 0:
        return 'C'

    if k >= 3:
        return 'D'

    if last_me == 'D':
        if k == 1:
            return 'C'
        else:
            return 'D'
    else:
        if n >= 3 and me[-2] == 'D' and k <= 2:
            return 'C'
        else:
            return 'D'
